css:
html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  border: none;

  background: transparent !important;
  pointer-events: none;
}

.shredder-widget,
.shredder-widget * {
  box-sizing: border-box;
  pointer-events: none;
}

.shredder-widget {
  /* Estado inicial: rojo. */
  --shredder-border: #8F3932;
  --shredder-fill-light: #F3C6C2;
  --shredder-fill-middle: #E69A93;
  --shredder-fill-base: #D87971;

  display: block;
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;

  background: transparent;
  opacity: var(--w-opacity, 1);
  user-select: none;
}

/* BOOL = 0: todo el símbolo en tonos rojos. */
.shredder-widget[data-state="0"] {
  --shredder-border: #8F3932;
  --shredder-fill-light: #F3C6C2;
  --shredder-fill-middle: #E69A93;
  --shredder-fill-base: #D87971;
}

/* BOOL = 1: todo el símbolo en tonos verdes. */
.shredder-widget[data-state="1"] {
  --shredder-border: #47733B;
  --shredder-fill-light: #F1FAEC;
  --shredder-fill-middle: #DDF1CF;
  --shredder-fill-base: #CCE7BB;
}

.shredder-svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: hidden;

  background: transparent;
  shape-rendering: geometricPrecision;
}

.shredder-fill-light {
  stop-color: var(--shredder-fill-light);
}

.shredder-fill-middle {
  stop-color: var(--shredder-fill-middle);
}

.shredder-fill-base {
  stop-color: var(--shredder-fill-base);
}

/* Mismo grosor de borde para ejes y aspas. */
.shredder-blade,
.shredder-shaft {
  stroke: var(--shredder-border);
  stroke-width: 0.9;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.shredder-blade {
  fill: url("#shredder-surface");
}

.shredder-shaft {
  fill: url("#shredder-shaft-surface");
}

.shredder-blade-shadow {
  fill: none;
  stroke: var(--shredder-border);
  stroke-width: 0.65;
  stroke-linecap: round;
  opacity: 0.15;
}

js:
"use strict";

(function () {
  let container = null;
  let latestWidget = window.WIDGET || {};

  function isActive(value) {
    if (value === true || value === 1) {
      return true;
    }

    if (typeof value === "string") {
      const normalized = value.trim().toLowerCase();

      return (
        normalized === "1" ||
        normalized === "true"
      );
    }

    // Sin dato o valor no reconocido: rojo.
    return false;
  }

  function render(widget) {
    if (!container) {
      return;
    }

    const state = isActive(widget.value) ? "1" : "0";

    // Cambia conjuntamente rellenos, bordes y sombras.
    container.setAttribute("data-state", state);

    container.setAttribute(
      "aria-label",
      "Desmenuzador de fibra: estado " + state
    );
  }

  window.onWidgetUpdate = function (widget) {
    latestWidget = widget || {};
    render(latestWidget);
  };

  function initialize() {
    container = document.querySelector(".shredder-widget");
    render(latestWidget);
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      initialize,
      { once: true }
    );
  } else {
    initialize();
  }
})();
